import '@design-schema/lit';
import { html, type TemplateResult } from 'lit';
import type { LinkTone } from '@design-schema/lit';

interface LinkArgs {
  href: string;
  label: string;
  external: boolean;
  tone: LinkTone;
  download: boolean;
}

const link = (args: LinkArgs): TemplateResult => html`<ds-link
  href=${args.href}
  label=${args.label}
  tone=${args.tone}
  ?external=${args.external}
  ?download=${args.download}
></ds-link>`;

html`
  <ds-text tone="muted">For how charges are calculated, read ${link({ href: '/billing/history', label: 'View the billing history', tone: 'inherit' })}.</ds-text>
`;

